SELECT p.dod, a.admission_type_code, s.stay_status, percentile_cont(0.25) within GROUP (ORDER BY s.length_of_stay) AS q25, percentile_cont(0.50) within GROUP (ORDER BY s.length_of_stay) AS q50, percentile_cont(0.75) within GROUP (ORDER BY s.length_of_stay) AS q75, percentile_cont(0.90) within GROUP (ORDER BY s.length_of_stay) AS q90 FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays s ON a.subject_id = s.subject_id WHERE p.gender = 'F' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 49 AND a.admission_type_code = 'E' AND EXTRACT(YEAR FROM p.anchor_year) BETWEEN 44 AND 54 AND s.stay_status IN ('Alive', 'Dead') GROUP BY p.dod, a.admission_type_code, s.stay_status ORDER BY p.dod, a.admission_type_code, s.stay_status NULLS LAST;